{"name": "btc_price_monitor_7d", "version": "2.0.0", "entrypoint": "fetch_price", "max_iterations": 20, "nodes": [{"id": "fetch_price", "kind": "task", "action": {"mode": "sync", "request": {"url": "http://ritesmith-latency:8081/trama/execute", "verb": "POST", "headers": {"Authorization": "Bearer __TRAMA_TOKEN__", "Content-Type": "application/json"}, "body": {"capability_name": "market.bitcoin_price", "input": {"currency": "usd"}}}, "successStatusCodes": [200]}, "next": "decide_price"}, {"id": "decide_price", "kind": "switch", "cases": [{"name": "above_threshold", "when": {">": [{"var": "nodes.fetch_price.response.body.output.price"}, 100000]}, "target": "notify_telegram"}], "default": "tick"}, {"id": "notify_telegram", "kind": "task", "action": {"mode": "sync", "request": {"url": "http://ritesmith-latency:8081/trama/execute", "verb": "POST", "headers": {"Authorization": "Bearer __TRAMA_TOKEN__", "Content-Type": "application/json"}, "body": {"capability_name": "telegram.send_markdown", "input": {"text": "*BTC acima de US$ 100.000*
