Atualizado em: {{ nodes.fetch_price.response.body.output.timestamp }}"}}}, "successStatusCodes": [200]}, "next": "tick"}, {"id": "tick", "kind": "task", "action": {"mode": "sync", "request": {"url": "http://ritesmith-latency:8081/trama/execute", "verb": "POST", "headers": {"Authorization": "Bearer __TRAMA_TOKEN__", "Content-Type": "application/json"}, "body": {"capability_name": "stat.tick", "input": {"iteration": "{{ nodes.tick.response.body.output.iteration }}", "state": {"last_price_usd": "{{ nodes.fetch_price.response.body.output.price }}", "last_timestamp": "{{ nodes.fetch_price.response.body.output.timestamp }}"}}}}, "successStatusCodes": [200]}, "next": "check"}, {"id": "check", "kind": "switch", "cases": [{"name": "spawn_next_chain_after_20", "when": {"and": [{"==": [{"var": "payload.continuation.remaining"}, null]}, {">=": [{"var": "nodes.tick.response.body.output.iteration"}, 20]}]}, "target": "spawn_next"}, {"name": "done_final_chain", "when": {"and": [{"!=": [{"var": "payload.continuation.remaining"}, null]}, {">=": [{"var": "nodes.tick.response.body.output.iteration"}, {"var": "payload.continuation.remaining"}]}]}, "target": "finish"}], "default": "wait"}, {"id": "wait", "kind": "sleep", "durationSeconds": 21600, "next": "fetch_price"}, {"id": "spawn_next", "kind": "task", "action": {"mode": "sync", "request": {"url": "http://ritesmith-latency:8081/plans", "verb": "POST", "headers": {"Content-Type": "application/json"}, "body": {"intent": "Monitor BTC four times daily for seven days, notify on Telegram when price is above 100000 USD", "mode": "execute", "replan_budget": 0, "context": {"continuation": {"remaining": 8}}}}, "successStatusCodes": [200, 201]}, "next": "end"}, {"id": "finish", "kind": "task", "action": {"mode": "sync", "request": {"url": "http://ritesmith-latency:8081/trama/execute", "verb": "POST", "headers": {"Authorization": "Bearer __TRAMA_TOKEN__", "Content-Type": "application/json"}, "body": {"capability_name": "runtime.now", "input": {}}}, "successStatusCodes": [200]}, "next": "end"}]}
